        when {
            process {
                """
                input[0] = [ [ id:'test' ], file('${hto_matrix}'), "COMBINED", "FALSE" ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }
    }



